const loadGame=async()=>{const h=location.hash.slice(1).split("/")[1],n=parseInt(h);if(!n||isNaN(n))return redirect();if(!games){try{const c=new AbortController(),t=setTimeout(()=>c.abort(),5000),r=await fetch("/assets/json/games.json",{signal:c.signal});clearTimeout(t);if(!r.ok)throw new Error("Invalid response");games=await r.json()}catch(e){console.error("Failed to load games.json:",e);return redirect()}}const g=games.find(g=>g.number===n);if(!g)return redirect();document.title=`${g.name} - HyperRush`;if(iframe)iframe.remove();iframe=document.createElement("iframe");iframe.src=g.link;iframe.setAttribute("sandbox","allow-scripts allow-same-origin");iframe.onload=()=>{injectIntoIframe();iframe.style.display="block";document.getElementById("loader").style.display="none"};iframe.onerror=()=>redirect();document.body.appendChild(iframe)};
window.addEventListener("hashchange",()=>loadGame());
loadGame();
